Create a `TooltipContext` to manage the state of the tooltip and a `useTooltip` hook to use the context.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  return (
    <TooltipContext.Provider value={{ tooltip, setTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);

  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }

  return context;
};
```

Now, create the Tooltip component that uses the `useTooltip` hook to access the context and manage the tooltip state.

```jsx
import React, { useEffect } from 'react';
import { useTooltip } from './TooltipContext';

const Tooltip = ({ children, placement = 'bottom', delay = 0 }) => {
  const { tooltip, setTooltip, closeTooltip } = useTooltip();

  const handleMouseEnter = (event) => {
    event.persist();

    setTimeout(() => {
      setTooltip({
        event,
        content: children,
        placement,
      });
    }, delay);
  };

  const handleMouseLeave = () => {
    closeTooltip();
  };

  useEffect(() => {
    if (tooltip) {
      document.addEventListener('mousemove', handleMouseMove);
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
    };
  }, [tooltip]);

  const handleMouseMove = (event) => {
    if (tooltip && tooltip.placement === 'top') {
      setTooltip({
        ...tooltip,
        top: event.clientY + tooltip.content.props.style.height + 10,
      });
    } else if (tooltip && tooltip.placement === 'bottom') {
      setTooltip({
        ...tooltip,
        top: event.clientY - tooltip.content.props.style.height - 10,
      });
    }
  };

  return (
    <>
      {tooltip && (
        <div
          className="tooltip"
          style={{
            ...tooltip.style,
            left: tooltip.left,
            top: tooltip.top,
          }}
        >
          {tooltip.content}
        </div>
      )}
      <div
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        ref={tooltip ? null : tooltipRef}
      >
        {children}
      </div>
    </>
  );
};

export default Tooltip;
```

