Here's a sample code for a TCP client in C# that performs the tasks you've described:

```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;

namespace TCPClient
{
    class Program
    {
        static void Main(string[] args)
        {
            try
            {
                // Create a TCP client.
                TcpClient client = new TcpClient("192.168.0.3", 40957);

                // Get a stream for reading from the server.
                NetworkStream stream = client.GetStream();

                // Send the login message.
                byte[] sendBuffer = Encoding.ASCII.GetBytes("LGIN x-stream");
                stream.Write(sendBuffer, 0, sendBuffer.Length);

                // Receive the server's response.
                byte[] receiveBuffer = new byte[1024];
                int bytesRead = stream.Read(receiveBuffer, 0, receiveBuffer.Length);
                string responseData = Encoding.ASCII.GetString(receiveBuffer, 0, bytesRead);

                Console.WriteLine($"Server response: {responseData}");

                // If the password is correct, send the GTMP? message and read the temperature.
                if (responseData.Contains("Password correct"))
                {
                    sendBuffer = Encoding.ASCII.GetBytes("GTMP?");
                    stream.Write(sendBuffer, 0, sendBuffer.Length);

                    receiveBuffer = new byte[1024];
                    bytesRead = stream.Read(receiveBuffer, 0, receiveBuffer.Length);
                    responseData = Encoding.ASCII.GetString(receiveBuffer, 0, bytesRead);

                    Console.WriteLine($"Temperature: {responseData}");
                }

                // Send the LOGOUT message to close the connection.
                sendBuffer = Encoding.ASCII.GetBytes("LOGOUT");
                stream.Write(sendBuffer, 0, sendBuffer.Length);

                // Close everything.
                stream.Close();
                client.Close();
            }
            catch (Exception e)
            {
                Console.WriteLine("Error: " + e);
            }

            Console.ReadLine();
        }
    }
}
```

This code creates a TCP client, connects to the specified IP address and port, sends the login message, reads the server's response, sends the GTMP? message if the password is correct, reads the temperature, sends the LOGOUT message, and closes the connection.

